let all = Array(1...100)
func prefetch(_ row: Int, ahead: Int) -> [Int] {
    Array(all[row..<row + ahead])
}
print(prefetch(5, ahead: 3))

var last = 0.0
func ready(_ t: Double) -> Bool {
    defer { last = t }
    return t - last > 0.5
}
print(ready(1.0), ready(1.2))

